PRAGMA foreign_keys = ON;
CREATE TABLE users (telegram_user_id TEXT PRIMARY KEY, username TEXT, display_name TEXT, status TEXT NOT NULL DEFAULT 'ACTIVE' CHECK(status IN('ACTIVE','DISABLED')), auth_epoch INTEGER NOT NULL DEFAULT 1, created_at INTEGER NOT NULL, last_seen_at INTEGER NOT NULL, notes TEXT NOT NULL DEFAULT '');
CREATE TABLE installations (installation_id TEXT PRIMARY KEY, public_key_sha256 TEXT NOT NULL UNIQUE, spki TEXT NOT NULL, root_spki_sha256 TEXT NOT NULL, security_level TEXT NOT NULL CHECK(security_level IN('TEE','STRONGBOX')), evidence_key TEXT NOT NULL, evidence_sha256 TEXT NOT NULL, attestation_json TEXT NOT NULL, device_json TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE installation_attestation_serials (installation_id TEXT NOT NULL REFERENCES installations ON DELETE RESTRICT, serial TEXT NOT NULL, PRIMARY KEY(installation_id,serial));
CREATE TABLE bindings (binding_id TEXT PRIMARY KEY, installation_id TEXT NOT NULL REFERENCES installations, telegram_user_id TEXT NOT NULL REFERENCES users, status TEXT NOT NULL CHECK(status IN('ACTIVE','ENDED')), created_at INTEGER NOT NULL, ended_at INTEGER);
CREATE UNIQUE INDEX bindings_active_installation ON bindings(installation_id) WHERE status='ACTIVE';
CREATE TABLE credentials (credential_id TEXT PRIMARY KEY, installation_id TEXT NOT NULL REFERENCES installations, binding_id TEXT NOT NULL REFERENCES bindings, token_sha256 TEXT NOT NULL UNIQUE, auth_epoch INTEGER NOT NULL, status TEXT NOT NULL CHECK(status IN('ACTIVE','REVOKED')), created_at INTEGER NOT NULL, revoked_at INTEGER);
CREATE UNIQUE INDEX credentials_active_installation ON credentials(installation_id) WHERE status='ACTIVE';
CREATE TABLE registration_contexts (registration_id TEXT PRIMARY KEY, mode TEXT NOT NULL CHECK(mode IN('NEW_KEY','REGISTERED_KEY')), existing_installation_id TEXT REFERENCES installations, token_sha256 TEXT NOT NULL, registration_nonce TEXT NOT NULL, attestation_challenge TEXT, state TEXT NOT NULL CHECK(state IN('PREPARED','REGISTERED','EXPIRED')), expires_at INTEGER NOT NULL, created_at INTEGER NOT NULL, installation_id TEXT REFERENCES installations, evidence_submission_sha256 TEXT, UNIQUE(token_sha256,registration_nonce,mode));
CREATE TABLE enrollment_sessions (binding_session_id TEXT PRIMARY KEY, registration_id TEXT NOT NULL UNIQUE REFERENCES registration_contexts, installation_id TEXT NOT NULL REFERENCES installations, token_sha256 TEXT NOT NULL UNIQUE, code_hmac TEXT UNIQUE, code_wrapped_json TEXT, confirm_nonce TEXT UNIQUE, candidate_user_id TEXT REFERENCES users, candidate_chat_id TEXT, candidate_epoch INTEGER, state TEXT NOT NULL CHECK(state IN('PENDING','APPROVED','CLAIMED','EXPIRED','CANCELLED')), expires_at INTEGER NOT NULL, created_at INTEGER NOT NULL, claimed_at INTEGER, binding_id TEXT REFERENCES bindings, credential_id TEXT REFERENCES credentials);
CREATE TABLE challenges (challenge_id TEXT PRIMARY KEY, actor_type TEXT NOT NULL CHECK(actor_type IN('REGISTRATION','CREDENTIAL')), actor_id TEXT NOT NULL, method TEXT NOT NULL, path TEXT NOT NULL, process_nonce TEXT NOT NULL, grant_id TEXT NOT NULL DEFAULT '', nonce TEXT NOT NULL, expires_at INTEGER NOT NULL, consumption_id TEXT UNIQUE, consumed_request_id TEXT, created_at INTEGER NOT NULL);
CREATE TRIGGER challenge_no_reuse BEFORE UPDATE OF consumption_id ON challenges WHEN OLD.consumption_id IS NOT NULL AND NEW.consumption_id IS NOT OLD.consumption_id BEGIN SELECT RAISE(ABORT,'challenge already consumed'); END;
CREATE TABLE request_operations (actor_type TEXT NOT NULL, actor_id TEXT NOT NULL, operation TEXT NOT NULL, request_id TEXT NOT NULL, operation_digest TEXT NOT NULL, result_json TEXT NOT NULL, created_at INTEGER NOT NULL, PRIMARY KEY(actor_type,actor_id,operation,request_id));
CREATE TABLE request_attempts (attempt_id TEXT PRIMARY KEY, actor_type TEXT NOT NULL, actor_id TEXT NOT NULL, operation TEXT NOT NULL, request_id TEXT NOT NULL, current_result TEXT NOT NULL, source_ip TEXT NOT NULL, source_type TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE auth_rejections (id INTEGER PRIMARY KEY AUTOINCREMENT, code TEXT NOT NULL, request_id TEXT, source_ip TEXT, created_at INTEGER NOT NULL);
CREATE TABLE attestation_snapshots (snapshot_id TEXT PRIMARY KEY, fetched_at INTEGER NOT NULL, roots_sha256 TEXT NOT NULL, status_sha256 TEXT NOT NULL);
CREATE TABLE attestation_roots (snapshot_id TEXT NOT NULL REFERENCES attestation_snapshots, spki_sha256 TEXT NOT NULL, pem TEXT NOT NULL, PRIMARY KEY(snapshot_id,spki_sha256));
CREATE TABLE attestation_revocations (snapshot_id TEXT NOT NULL REFERENCES attestation_snapshots, serial TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN('REVOKED','SUSPENDED')), PRIMARY KEY(snapshot_id,serial));
CREATE TABLE attestation_current (singleton INTEGER PRIMARY KEY CHECK(singleton=1), snapshot_id TEXT NOT NULL REFERENCES attestation_snapshots);
CREATE TABLE payload_releases (payload_id TEXT PRIMARY KEY, manifest_json TEXT NOT NULL, apk_sha256 TEXT NOT NULL, apk_size INTEGER NOT NULL, cipher_sha256 TEXT NOT NULL, cipher_size INTEGER NOT NULL, r2_key TEXT NOT NULL UNIQUE, content_key_wrapped_json TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN('UPLOADING','READY','ALLOWED','STOPPED','FAILED')), created_at INTEGER NOT NULL);
CREATE TABLE channels (name TEXT PRIMARY KEY, payload_id TEXT NOT NULL REFERENCES payload_releases, updated_at INTEGER NOT NULL);
CREATE TABLE initializations (initialization_id TEXT PRIMARY KEY, credential_id TEXT NOT NULL REFERENCES credentials, binding_id TEXT NOT NULL REFERENCES bindings, installation_id TEXT NOT NULL REFERENCES installations, telegram_user_id TEXT NOT NULL REFERENCES users, request_id TEXT NOT NULL, process_nonce TEXT NOT NULL, source_ip TEXT NOT NULL, source_type TEXT NOT NULL, self_wx_id TEXT, self_alias TEXT, host_version_name TEXT NOT NULL, bootstrap_version TEXT NOT NULL, process_name TEXT NOT NULL, report_json TEXT NOT NULL, result TEXT NOT NULL, payload_id TEXT REFERENCES payload_releases, created_at INTEGER NOT NULL, UNIQUE(credential_id,request_id));
CREATE TABLE load_grants (grant_id TEXT PRIMARY KEY, initialization_id TEXT NOT NULL REFERENCES initializations, credential_id TEXT NOT NULL REFERENCES credentials, binding_id TEXT NOT NULL REFERENCES bindings, auth_epoch INTEGER NOT NULL, process_nonce TEXT NOT NULL, payload_id TEXT NOT NULL REFERENCES payload_releases, apk_sha256 TEXT NOT NULL, expires_at INTEGER NOT NULL, revoked INTEGER NOT NULL DEFAULT 0 CHECK(revoked IN(0,1)), created_at INTEGER NOT NULL);
CREATE TABLE initialization_reports (report_id TEXT PRIMARY KEY, initialization_id TEXT NOT NULL REFERENCES initializations, request_id TEXT NOT NULL, stage TEXT NOT NULL, result TEXT NOT NULL, report_json TEXT NOT NULL, source_ip TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE telegram_updates (bot_id TEXT NOT NULL, update_id TEXT NOT NULL, attempt_id TEXT NOT NULL UNIQUE, result TEXT NOT NULL, binding_session_id TEXT REFERENCES enrollment_sessions, created_at INTEGER NOT NULL, PRIMARY KEY(bot_id,update_id));
CREATE TABLE admin_audit (audit_id INTEGER PRIMARY KEY AUTOINCREMENT, subject TEXT NOT NULL, email TEXT NOT NULL, action TEXT NOT NULL, target TEXT NOT NULL, reason TEXT NOT NULL, before_json TEXT NOT NULL, after_json TEXT NOT NULL, source_ip TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE publication_jobs (job_id TEXT PRIMARY KEY, payload_id TEXT NOT NULL UNIQUE REFERENCES payload_releases, ci_subject TEXT NOT NULL, source_commit TEXT NOT NULL, run_id TEXT NOT NULL, upload_id TEXT NOT NULL, state TEXT NOT NULL CHECK(state IN('UPLOADING','READY','ALLOWED','FAILED')), error_code TEXT, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE TABLE publication_parts (job_id TEXT NOT NULL REFERENCES publication_jobs, part_number INTEGER NOT NULL, sha256 TEXT NOT NULL, size INTEGER NOT NULL, etag TEXT NOT NULL, PRIMARY KEY(job_id,part_number));
CREATE INDEX initialization_user_time ON initializations(telegram_user_id,created_at,initialization_id);
CREATE INDEX initialization_installation_time ON initializations(installation_id,created_at,initialization_id);
CREATE INDEX initialization_wxid_time ON initializations(self_wx_id,created_at,initialization_id);
CREATE INDEX initialization_alias_time ON initializations(self_alias,created_at,initialization_id);
CREATE INDEX initialization_ip_time ON initializations(source_ip,created_at,initialization_id);
CREATE INDEX audit_actor_time ON admin_audit(subject,created_at,audit_id);
CREATE INDEX audit_target_time ON admin_audit(target,created_at,audit_id);
CREATE INDEX grant_initialization ON load_grants(initialization_id,created_at);
CREATE INDEX bindings_user ON bindings(telegram_user_id,created_at);
CREATE INDEX challenges_expiry ON challenges(expires_at);
CREATE INDEX contexts_expiry ON registration_contexts(expires_at);
CREATE INDEX sessions_expiry ON enrollment_sessions(expires_at);
